import { downloadAGGridCsv, getCellValue } from '../agGrid';

describe('agGrid utils', () => {
  describe('downloadAGGridCsv', () => {
    const generateCsvData = ({ rowData, column }) => rowData[column.index];

    const generateBadCsvData = () => null;

    it('creates csv document and clicks link', () => {
      jest.spyOn(document, 'createElement');
      jest.spyOn(document.body, 'appendChild');

      const csvString = downloadAGGridCsv({
        columnFormatters: [
          {
            headerName: 'First',
            generateCsvData,
          },
        ],
        csvFileName: 'fake_file_name',
        rows: [{ rowData: [[1], [2], [3], [4]] }],
      });
      expect(document.createElement).toHaveBeenCalledWith('a');
      expect(document.body.appendChild).toHaveBeenCalledTimes(1);
      expect(csvString).toMatchSnapshot();
    });

    it('creates csv document when there are multiple attempts', () => {
      jest.spyOn(document, 'createElement');
      jest.spyOn(document.body, 'appendChild');

      const columnFormatters = [
        {
          headerName: 'First',
          generateCsvData,
          children: [
            {
              headerName: 'Attempt 1',
              generateCsvData,
            },
            {
              headerName: 'Attempt 2',
              generateCsvData,
            },
          ],
          props: {
            listInstanceId: 'attempt_list_instance_id',
          },
        },
      ];

      const rows = [
        {
          id: 'fake_row_id',
          rowData: [{ id: 'fake_cell_value' }],
          attemptRows: {
            attempt_list_instance_id: [
              {
                rowData: [{ id: 'attempt_1' }, { id: 'attempt_2' }],
              },
            ],
          },
        },
      ];

      const csvString = downloadAGGridCsv({
        columnFormatters,
        csvFileName: 'fake_file_name',
        rows,
      });
      expect(csvString).toMatchSnapshot();
    });

    it('creates csv document with commas', () => {
      jest.spyOn(document, 'createElement');
      jest.spyOn(document.body, 'appendChild');

      const csvString = downloadAGGridCsv({
        columnFormatters: [
          {
            headerName: 'First',
            generateCsvData,
          },
          {
            headerName: 'Second',
            generateCsvData,
          },
          {
            headerName: 'Third',
            generateCsvData,
          },
          {
            headerName: 'Fourth',
            generateCsvData,
          },
        ],
        csvFileName: 'fake_file_name.csv',
        rows: [
          {
            rowData: [
              'Testing, with, a, comma',
              'another *&#() "cell" :)',
              3,
              4,
            ],
          },
        ],
      });
      expect(csvString).toMatchSnapshot();
    });

    it('creates csv document when generateCsvData returns null', () => {
      jest.spyOn(document, 'createElement');
      jest.spyOn(document.body, 'appendChild');

      const csvString = downloadAGGridCsv({
        columnFormatters: [
          {
            headerName: 'First',
            generateCsvData: generateBadCsvData,
          },
        ],
        csvFileName: 'fake_file_name',
        rows: [{ rowData: [[1], [2], [3], [4]] }],
      });
      expect(csvString).toMatchSnapshot();
    });

    it('works correctly when no rows data is passed in', () => {
      jest.spyOn(document, 'createElement');
      jest.spyOn(document.body, 'appendChild');

      const csvString = downloadAGGridCsv({
        columnFormatters: [
          {
            headerName: 'First',
            generateCsvData: generateBadCsvData,
          },
        ],
        csvFileName: 'fake_file_name',
      });
      expect(csvString).toMatchSnapshot();
    });
  });

  describe('getCellValue', () => {
    it('returns correct cell value', () => {
      const columnDefinition = {
        generateCsvData: (props) => props,
      };
      const columnIndex = 0;

      const cellValue = getCellValue({
        rowData: [],
        columnDefinition,
        columnIndex,
      });
      expect(cellValue).toEqual({
        rowData: [],
        column: {
          definition: columnDefinition,
          index: columnIndex,
        },
      });
    });

    it('returns correct cell value with a nestedLevel', () => {
      const columnDefinition = {
        generateCsvData: (props) => props,
      };
      const columnIndex = 0;

      const cellValue = getCellValue({
        rowData: [],
        columnDefinition,
        columnIndex,
        itemPath: ['12311', '13212312'],
      });
      expect(cellValue).toEqual({
        rowData: [],
        column: {
          definition: columnDefinition,
          index: columnIndex,
        },
        nestedLevel: 1,
      });
    });

    it('returns "--" when generateCsvData returns bad value', () => {
      const columnDefinition = {
        generateCsvData: () => null,
      };
      const columnIndex = 0;

      const cellValue = getCellValue({
        rowData: [],
        columnDefinition,
        columnIndex,
      });
      expect(cellValue).toEqual('--');
    });
  });
});
